635	// ----------------------------------------------------------------------------
636	// The Sampler, which takes logits and returns a sampled token
637	// sampling can be done in a few ways: greedy argmax, sampling, top-p sampling
638	
639	typedef struct {
640	    float prob;
641	    int index;
642	} ProbIndex; // struct used when sorting probabilities during top-p sampling
643	
644	typedef struct {
645	    int vocab_size;
646	    ProbIndex* probindex; // buffer used in top-p sampling
647	    float temperature;
648	    float topp;
649	    unsigned long long rng_state;
650	} Sampler;
651	
652	int sample_argmax(float* probabilities, int n) {
653	    // return the index that has the highest probability
654	    int max_i = 0;
655	    float max_p = probabilities[0];
656	    for (int i = 1; i < n; i++) {
657	        if (probabilities[i] > max_p) {
658	            max_i = i;
659	            max_p = probabilities[i];
660	        }
661	    }
662	    return max_i;
663	}
664	
665	int sample_mult(float* probabilities, int n, float coin) {
666	    // sample index from probabilities (they must sum to 1!)
667	    // coin is a random number in [0, 1), usually from random_f32()
668	    float cdf = 0.0f;
669	    for (int i = 0; i < n; i++) {
670	        cdf += probabilities[i];
671	        if (coin < cdf) {
672	            return i;
673	        }
674	    }
675	    return n - 1; // in case of rounding errors
676	}
677	
678	int compare(const void* a, const void* b) {
679	    ProbIndex* a_ = (ProbIndex*) a;
680	    ProbIndex* b_ = (ProbIndex*) b;
681	    if (a_->prob > b_->prob) return -1;
682	    if (a_->prob < b_->prob) return 1;
683	    return 0;
684	}
685	
686	int sample_topp(float* probabilities, int n, float topp, ProbIndex* probindex, float coin) {
687	    // top-p sampling (or "nucleus sampling") samples from the smallest set of
688	    // tokens that exceed probability topp. This way we never sample tokens that
689	    // have very low probabilities and are less likely to go "off the rails".
690	    // coin is a random number in [0, 1), usually from random_f32()
691	
692	    int n0 = 0;
693	    // quicksort indices in descending order of probabilities
694	    // values smaller than (1 - topp) / (n - 1) cannot be part of the result
695	    // so for efficiency we crop these out as candidates before sorting
696	    const float cutoff = (1.0f - topp) / (n - 1);
697	    for (int i = 0; i < n; i++) {
698	        if (probabilities[i] >= cutoff) {
699	            probindex[n0].index = i;
700	            probindex[n0].prob = probabilities[i];
701	            n0++;
702	        }
703	    }
704	    qsort(probindex, n0, sizeof(ProbIndex), compare);
705	
706	    // truncate the list where cumulative probability exceeds topp
707	    float cumulative_prob = 0.0f;
708	    int last_idx = n0 - 1; // in case of rounding errors consider all elements
709	    for (int i = 0; i < n0; i++) {
710	        cumulative_prob += probindex[i].prob;
711	        if (cumulative_prob > topp) {
712	            last_idx = i;
713	            break; // we've exceeded topp by including last_idx
714	        }
715	    }
716	
717	    // sample from the truncated list
718	    float r = coin * cumulative_prob;
719	    float cdf = 0.0f;
720	    for (int i = 0; i <= last_idx; i++) {
721	        cdf += probindex[i].prob;
722	        if (r < cdf) {
723	            return probindex[i].index;
724	        }
725	    }
726	    return probindex[last_idx].index; // in case of rounding errors
727	}
728	
729	void build_sampler(Sampler* sampler, int vocab_size, float temperature, float topp, unsigned long long rng_seed) {
730	    sampler->vocab_size = vocab_size;
731	    sampler->temperature = temperature;
732	    sampler->topp = topp;
733	    sampler->rng_state = rng_seed;
734	    // buffer only used with nucleus sampling; may not need but it's ~small
735	    sampler->probindex = malloc(sampler->vocab_size * sizeof(ProbIndex));
736	}
737	
738	void free_sampler(Sampler* sampler) {
739	    free(sampler->probindex);
740	}
741	
742	unsigned int random_u32(unsigned long long *state) {
743	    // xorshift rng: https://en.wikipedia.org/wiki/Xorshift#xorshift.2A
744	    *state ^= *state >> 12;
745	    *state ^= *state << 25;
746	    *state ^= *state >> 27;
747	    return (*state * 0x2545F4914F6CDD1Dull) >> 32;
748	}
749	float random_f32(unsigned long long *state) { // random float32 in [0,1)
750	    return (random_u32(state) >> 8) / 16777216.0f;
751	}
752	
753	int sample(Sampler* sampler, float* logits) {
754	    // sample the token given the logits and some hyperparameters
755	    int next;
756	    if (sampler->temperature == 0.0f) {
757	        // greedy argmax sampling: take the token with the highest probability
758	        next = sample_argmax(logits, sampler->vocab_size);
759	    } else {
760	        // apply the temperature to the logits
761	        for (int q=0; q<sampler->vocab_size; q++) { logits[q] /= sampler->temperature; }
762	        // apply softmax to the logits to get the probabilities for next token
763	        softmax(logits, sampler->vocab_size);
764	        // flip a (float) coin (this is our source of entropy for sampling)
765	        float coin = random_f32(&sampler->rng_state);
766	        // we sample from this distribution to get the next token
767	        if (sampler->topp <= 0 || sampler->topp >= 1) {
768	            // simply sample from the predicted probability distribution
769	            next = sample_mult(logits, sampler->vocab_size, coin);
770	        } else {
771	            // top-p (nucleus) sampling, clamping the least likely tokens to zero
772	            next = sample_topp(logits, sampler->vocab_size, sampler->topp, sampler->probindex, coin);
773	        }
774	    }
775	    return next;
776	}
