789	// generation loop
790	
791	void generate(Transformer *transformer, Tokenizer *tokenizer, Sampler *sampler, char *prompt, int steps) {
792	    char *empty_prompt = "";
793	    if (prompt == NULL) { prompt = empty_prompt; }
794	
795	    // encode the (string) prompt into tokens sequence
796	    int num_prompt_tokens = 0;
797	    int* prompt_tokens = (int*)malloc((strlen(prompt)+3) * sizeof(int)); // +3 for '\0', ?BOS, ?EOS
798	    encode(tokenizer, prompt, 1, 0, prompt_tokens, &num_prompt_tokens);
799	    if (num_prompt_tokens < 1) {
800	        fprintf(stderr, "something is wrong, expected at least 1 prompt token\n");
801	        exit(EXIT_FAILURE);
802	    }
803	
804	    // start the main loop
805	    long start = 0;  // used to time our code, only initialized after first iteration
806	    int next;        // will store the next token in the sequence
807	    int token = prompt_tokens[0]; // kick off with the first token in the prompt
808	    int pos = 0;     // position in the sequence
809	    while (pos < steps) {
810	
811	        // forward the transformer to get logits for the next token
812	        float* logits = forward(transformer, token, pos);
813	
814	        // advance the state machine
